// Turns a boolean machine signal into START/END events for the platform.
// msg.payload: true = active, false = inactive - e.g. from an S7, OPC UA or Modbus node.
// Configure per node: CATEGORY = PROCESS (cycle running), ERROR (alarm bit), SETUP (changeover) ...
const CATEGORY = "PROCESS";
const ASSET = env.get("ASSET_ID") || "LINE-01-M01";   // set in the flow/tab environment
const SITE = env.get("SITE_ID") || "site1";

const active = msg.payload === true || msg.payload === 1 || msg.payload === "true";
const stateKey = "active_" + CATEGORY, uidKey = "uid_" + CATEGORY;
if (context.get(stateKey) === active) return null;      // react on edges only
context.set(stateKey, active);

let event;
if (active) {
    const uid = ASSET + "-" + CATEGORY + "-" + Date.now();
    context.set(uidKey, uid);
    event = { event_uid: uid, event_state: "START" };
} else {
    const uid = context.get(uidKey);
    if (!uid) return null;                               // END without START (e.g. after a restart)
    context.set(uidKey, null);
    event = { event_uid: uid, event_state: "END" };
    // Optional: produced quantities for OEE quality, e.g. from a part counter:
    // event.quantity_good = msg.good; event.quantity_scrap = msg.scrap;
}
event.asset_id = ASSET;
event.event_category = CATEGORY;
event.event_datetime = new Date().toISOString();        // gateway clock -> keep it NTP-synced
if (msg.code !== undefined) event.event_code = String(msg.code);

return { topic: "oee/" + SITE + "/" + ASSET + "/events", payload: event, qos: 1 };

